# Exploratory run 3: cost formulas in instrument + variable consistency checks (no RESULT lines)
suppressMessages({library(haven); library(dplyr); library(readxl)})
options(width = 250)
B <- "<repo>/benchmark/.cache/claude-code/bold-2022-market-access-quality-upgrading/blind/2026-11-10-c/mount/bold_2022_market_access_quality_upgrading/"
M <- paste0(B, "data/raw/")
s <- as.data.frame(read_excel(paste0(B, "survey_materials/main_survey/survey_instrument_main.xlsx"), sheet = "survey"))
for (nm in c("tot_costs_pre", "tot_costs_post", "labor_cost_ph_check", "otherph_cost_check", "labor_cost_dry", "drying_cost", "labor_cost_store", "storage_cost", "labor_cost_ph", "otherph_cost", "tot_lab_costs_1", "tot_chem_costs_1", "equipment_cost_1", "harvest_kg", "acres_tot", "home_kg_1st", "kgs_measure_resp", "seeds_cost_1", "lc_prep_costs_unit1", "lc_prep_ppl_season1", "lc_prep_units_season1", "lh_prep_ppl_season1", "lh_prep_hours_unit1", "sale_transport_cost", "harvest_cost_1")) {
  i <- which(s$name == nm)
  for (j in i) cat(nm, ":: TYPE", s$type[j], ":: LABEL", substr(s$`label::english`[j], 1, 300), ":: CALC", s$calculation[j], ":: REL", s$relevant[j], "\n\n")
}
g <- read_dta(paste0(M, "panel_g1.dta"))
sumv <- function(pref, P = 6) { m <- sapply(1:P, function(p) { v <- paste0(pref, p); if (v %in% names(g)) g[[v]] else rep(NA_real_, nrow(g)) }); rowSums(m, na.rm = TRUE) * ifelse(rowSums(!is.na(m)) > 0, 1, NA) }
lc <- 0; for (t in c("prep", "plant", "weed", "spray", "harv")) lc <- lc + sumv(paste0("lc_", t, "_costs_season"))
tl <- sumv("tot_lab_costs_")
cat("tot_lab_costs vs lc sum: cor", cor(tl, lc, use = "c"), " mean diff", mean(tl - lc, na.rm = TRUE), " share equal", mean(abs(tl - lc) < 1, na.rm = TRUE), "\n")
hk <- sumv("harvest_kg_")
cat("harvest_kg vs plot sum: share equal", mean(abs(g$harvest_kg - hk) < 1, na.rm = TRUE), " n both", sum(!is.na(g$harvest_kg) & !is.na(hk)), "\n")
ps <- sumv("plot_size_", 12)
cat("acres_tot vs plot sum: share equal", mean(abs(g$acres_tot - ps) < 0.01, na.rm = TRUE), " cor", cor(g$acres_tot, ps, use = "c"), "\n")
cat("acres by season nonNA (acres_tot | plot sum):\n"); print(rbind(tapply(!is.na(g$acres_tot), g$survey_season, sum), tapply(!is.na(ps), g$survey_season, sum), tapply(!is.na(g$harvest_kg) | !is.na(hk), g$survey_season, sum)))
ph <- rowSums(cbind(g$lc_decob_labour_costs, g$lc_winnow_labour_costs, g$lc_sort_labour_costs, g$lc_bag_labour_costs), na.rm = TRUE)
cat("labor_cost_ph vs components: share equal", mean(abs(g$labor_cost_ph - ph) < 1, na.rm = TRUE), "\n")
op <- rowSums(cbind(g$lc_decob_other_costs, g$lc_winnow_other_costs, g$lc_sort_other_costs, g$lc_bag_other_costs), na.rm = TRUE)
cat("otherph vs components: share equal", mean(abs(g$otherph_cost - op) < 1, na.rm = TRUE), " by season:\n"); print(tapply(abs(g$otherph_cost - op) < 1, g$survey_season, mean, na.rm = TRUE))
cat("tot_transport vs pre+post equal share:", mean(abs(g$tot_transport_cost - g$cost_transportpre - g$cost_transportpost) < 1, na.rm = TRUE), "\n")
cat("labor_cost_dry <= drying_cost share:", mean(g$labor_cost_dry <= g$drying_cost, na.rm = TRUE), " labor_cost_store<=storage_cost:", mean(g$labor_cost_store <= g$storage_cost, na.rm = TRUE), "\n")
cat("units for lc (all plots, all tasks):\n"); print(table(unlist(g[, grep("^lc_.*_unit[0-9]$", names(g))])))
cat("units for lh:\n"); print(table(unlist(g[, grep("^lh_.*_unit[0-9]$", names(g))])))
cat("lh hours/unit when unit=days: median", median(unlist(g[, grep("^lh_.*_hours_unit[0-9]$", names(g))])[unlist(g[, grep("^lh_.*_unit[0-9]$", names(g))]) == "days"], na.rm = TRUE), "\n")
x <- unlist(g[, grep("^lc_.*_costs_unit[0-9]$", names(g))]); u <- unlist(g[, grep("^lc_.*_unit[0-9]$", names(g))])
for (uu in c("hours", "days", "season")) cat("lc cost/unit for", uu, ": quantiles", quantile(x[u == uu & x > 0], c(.1, .25, .5, .75, .9), na.rm = TRUE), "\n")
cat("lc unit by season:\n"); print(table(rep(g$survey_season, length(grep("^lc_.*_unit[0-9]$", names(g)))), u))
cat("lh total own hours by season (sum over tasks & plots):\n")
lh <- 0; for (t in c("prep", "plant", "weed", "spray", "harv")) lh <- lh + sumv(paste0("lh_", t, "_hours_season"))
print(tapply(lh, g$survey_season, function(z) c(n = sum(!is.na(z)), mean = mean(z, na.rm = TRUE))))
cat("postharvest own hours vars lh_decob_hours etc nonNA by season:\n"); for (v in c("lh_decob_hours", "lh_winnow_hours", "lh_sort_hours", "lh_bag_hours")) print(tapply(!is.na(g[[v]]), g$survey_season, sum))
cat("hh with no baseline obs among follow-up hh:\n")
base <- unique(g$hhh_id[g$survey_season <= 3]); fol <- unique(g$hhh_id[g$survey_season >= 4]); cat(length(setdiff(fol, base)), "\n")
cat("follow-up hh count:", length(fol), " follow-up obs:", sum(g$survey_season >= 4), "\n")
sd <- read_dta(paste0(M, "seller_data.dta"))
cat("seller: name codes table head\n"); print(head(sort(table(sd$name), decreasing = TRUE), 15))
cat("seller hh-season with price: by season\n"); hs <- sd %>% filter(price > 0, sold_kg_p_ > 0) %>% distinct(hhh_id, survey_season); print(table(hs$survey_season))
gg <- g %>% select(hhh_id, survey_season) %>% mutate(ing = 1)
cat("seller hh-seasons not in g1:", nrow(anti_join(hs, gg, by = c("hhh_id", "survey_season"))), "\n")
cat("sold_kg_tot vs g1 sold total (sum sold_kg_p_) check\n")
sk <- sumv("sold_kg_p_", 7); cat("g1 sold_kg_p_ sum by season nonNA:", tapply(!is.na(sk), g$survey_season, sum), "\n")
cat("harvest < sold share:", mean(hk < sk, na.rm = TRUE), "\n")
